style.css:
/* ★ iMØD3.exe — roblox.com */

/* change these colors if you want */
:root {
  --my-pink: #ff42c8;
  --my-purple: #963dff;
  --my-cyan: #38eaff;
  --my-blue: #248cff;
  --my-green: #aaff59;
  --my-bg: #100d29;
  --my-text: #fceaff;
}

/* dreamy frutiger metro background */
html, body {
  background-color: var(--my-bg) !important;
  background-image:
    radial-gradient(ellipse at 15% 20%, #ff42c855, transparent 35%),
    radial-gradient(ellipse at 85% 15%, #38eaff55, transparent 35%),
    radial-gradient(ellipse at 75% 85%, #963dff66, transparent 40%),
    radial-gradient(ellipse at 10% 90%, #248cff55, transparent 35%),
    linear-gradient(135deg, #100d29, #211044, #091d38) !important;
  background-attachment: fixed !important;
  color: var(--my-text) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* shiny digital links */
a {
  color: var(--my-cyan) !important;
  text-shadow: 0 0 7px #38eaff99 !important;
  transition: .2s ease !important;
}

a:hover {
  color: var(--my-pink) !important;
  text-shadow: 0 0 12px var(--my-pink) !important;
}

/* glossy buttons */
button, [role="button"] {
  border-radius: 12px !important;
  border: 1px solid #ffffff55 !important;
  background-image: linear-gradient(
    135deg,
    #ff42c8,
    #963dff 55%,
    #248cff
  ) !important;
  color: white !important;
  box-shadow: 0 0 12px #963dff55 !important;
  transition: .2s ease !important;
}

button:hover, [role="button"]:hover {
  box-shadow: 0 0 18px #ff42c8aa !important;
  filter: brightness(1.2) !important;
}

/* glossy images */
img {
  border-radius: 12px !important;
}

/* nostalgic selection */
::selection {
  background: var(--my-pink) !important;
  color: white !important;
}

/* neon scrollbar */
::-webkit-scrollbar {
  width: 9px !important;
}

::-webkit-scrollbar-track {
  background: #100d29 !important;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(
    var(--my-pink),
    var(--my-purple),
    var(--my-cyan)
  ) !important;
  border-radius: 20px !important;
}
